Object.assign(window.CODELAB_OFFLINE_PACKS,{"topic-day0902implementqueueusingstacks":{"key":"topic-day0902implementqueueusingstacks","number":null,"title":"Day 09 02 Implement Queue using Stacks","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 09-02 Implement Queue using Stacks.py","code":"class MyQueue:\n\n    def __init__(self):\n        self.stackA, self.stackB, self.front = [], [], None\n\n    def push(self, x: int) -> None:\n        if len(self.stackA) == 0:\n            self.front = x\n        self.stackA.append(x)\n\n    def pop(self) -> int:\n        if len(self.stackB) == 0:\n            while len(self.stackA) > 0:\n                self.stackB.append(self.stackA.pop())\n        return self.stackB.pop()\n\n    def peek(self) -> int:\n        if len(self.stackB) > 0:\n            return self.stackB[-1]\n        return self.front\n\n    def empty(self) -> bool:\n        return len(self.stackA) == 0 and len(self.stackB) == 0\n\n\n# Your MyQueue object will be instantiated and called as such:\n# obj = MyQueue()\n# obj.push(x)\n# param_2 = obj.pop()\n# param_3 = obj.peek()\n# param_4 = obj.empty()","hash":"85aaed8faee03beb3e177c725321024da062e3352a4a17b055bcff154ae8a420","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 09-02 Implement Queue using Stacks.py"}]}],"sources":["solutions"]},"topic-day0902rottingoranges":{"key":"topic-day0902rottingoranges","number":null,"title":"Day 09 02 Rotting Oranges","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 09-02 Rotting Oranges.py","code":"class Solution:\n    def orangesRotting(self, grid: List[List[int]]) -> int:\n        ROTTEN_ORANGE = 2\n        FRESH_ORANGE = 1\n        DIRECTIONS = [(1, 0), (-1, 0), (0, 1), (0, -1)]\n        queue = deque()\n        numberOfRows, numberOfColumns = len(grid), len(grid[0])\n        freshOranges = 0\n        for rowNumber in range(numberOfRows):\n            for columnNumber in range(numberOfColumns):\n                if grid[rowNumber][columnNumber] == ROTTEN_ORANGE:\n                    queue.append((rowNumber, columnNumber))\n                elif grid[rowNumber][columnNumber] == FRESH_ORANGE:\n                    freshOranges += 1\n        queue.append((-1, -1))\n        minutesElapsed = -1\n        while queue:\n            rowNumber, columnNumber = queue.popleft()\n            if rowNumber == -1:\n                minutesElapsed += 1\n                if queue:\n                    queue.append((-1, -1))\n            else:\n                for direction in DIRECTIONS:\n                    neighbourRow, neighbourColumn = rowNumber + direction[0], columnNumber + direction[1]\n                    if numberOfRows > neighbourRow >= 0 and numberOfColumns > neighbourColumn >= 0:\n                        if grid[neighbourRow][neighbourColumn] == FRESH_ORANGE:\n                            grid[neighbourRow][neighbourColumn] = ROTTEN_ORANGE\n                            freshOranges -= 1\n                            queue.append((neighbourRow, neighbourColumn))\n        return minutesElapsed if freshOranges == 0 else -1","hash":"30f65a3f9da0600b79e9c5520762622903aaa0e50dd40b165fdeacebff7799ba","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 09-02 Rotting Oranges.py"}]}],"sources":["solutions"]},"topic-day1001binarytreepreordertraversal":{"key":"topic-day1001binarytreepreordertraversal","number":null,"title":"Day 10 01 Binary Tree Preorder Traversal","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 10-01 Binary Tree Preorder Traversal.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def preorderTraversal(self, root: Optional[TreeNode]) -> List[int]:\n        result = []\n        def helper(node):\n            if node:\n                result.append(node.val)\n                helper(node.left)\n                helper(node.right)\n        helper(root)\n        return result","hash":"a960ceea284616a04f9ab37542f85ab72bb1a2bdc9af0dcc331e024e4aeecbe6","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 10-01 Binary Tree Preorder Traversal.py"}]}],"sources":["solutions"]},"topic-day1001mergetwosortedlists":{"key":"topic-day1001mergetwosortedlists","number":null,"title":"Day 10 01 Merge Two Sorted Lists","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 10-01 Merge Two Sorted Lists.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def mergeTwoLists(self, l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:\n        dummyNode = ListNode('D')\n        currentNode = dummyNode\n        while l1 is not None and l2 is not None:\n            if l1.val <= l2.val:\n                currentNode.next = l1\n                l1 = l1.next\n            else:\n                currentNode.next = l2\n                l2 = l2.next\n            if currentNode and currentNode.next:\n                currentNode = currentNode.next\n        if l1 is None and l2 is not None:\n            currentNode.next = l2\n        elif l1 is not None and l2 is None:\n            currentNode.next = l1\n        else:\n            currentNode.next = None\n        return dummyNode.next","hash":"0d948a779e668ee2a324e5d36a9b7485f895e74ad917337102cd5baaa97d7686","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 10-01 Merge Two Sorted Lists.py"}]}],"sources":["solutions"]},"topic-day1002binarytreeinordertraversal":{"key":"topic-day1002binarytreeinordertraversal","number":null,"title":"Day 10 02 Binary Tree Inorder Traversal","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 10-02 Binary Tree Inorder Traversal.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def inorderTraversal(self, root: TreeNode) -> List[int]:\n        result, node = [], root\n        while node:\n            if node.left is None:\n                result.append(node.val)\n                node = node.right\n            else:\n                predecessor = node.left\n                while predecessor.right:\n                    predecessor = predecessor.right\n                predecessor.right = node\n                temp = node\n                node = node.left\n                temp.left = None\n        return result","hash":"01a22c4391bfa892ec60f244d90fddb64be211333aa04ec592f4367cb47095c8","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 10-02 Binary Tree Inorder Traversal.py"}]}],"sources":["solutions"]},"topic-day1002reverselinkedlist":{"key":"topic-day1002reverselinkedlist","number":null,"title":"Day 10 02 Reverse Linked List","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 10-02 Reverse Linked List.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def reverseList(self, head: ListNode) -> ListNode:\n        if head is None or head.next is None:\n            return head\n        tempNode = self.reverseList(head.next)\n        head.next.next = head\n        head.next = None\n        return tempNode","hash":"0095d0979bfbd2373ed4c35838559af4ead690d07d05f80f2aafa3c3ec49412a","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 10-02 Reverse Linked List.py"}]}],"sources":["solutions"]},"topic-day1003binarytreepostordertraversal":{"key":"topic-day1003binarytreepostordertraversal","number":null,"title":"Day 10 03 Binary Tree Postorder Traversal","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 10-03 Binary Tree Postorder Traversal.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def postorderTraversal(self, root: Optional[TreeNode]) -> List[int]:\n        result = []\n        def helper(node):\n            if node:\n                helper(node.left)\n                helper(node.right)\n                result.append(node.val)\n        helper(root)\n        return result","hash":"1f91f3ed5d0c510a6470be314f9d7e713a9f7cd4c0e616e69f6eb03e922f6b33","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 10-03 Binary Tree Postorder Traversal.py"}]}],"sources":["solutions"]},"topic-day1101binarytreelevelordertraversal":{"key":"topic-day1101binarytreelevelordertraversal","number":null,"title":"Day 11 01 Binary Tree Level Order Traversal","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 11-01 Binary Tree Level Order Traversal.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def levelOrder(self, root: TreeNode) -> List[List[int]]:\n        levels = []\n        if root is None:\n            return levels\n        level = 0\n        queue = deque([root,])\n        while queue:\n            levels.append([])\n            levelLength = len(queue)\n            for i in range(levelLength):\n                node = queue.popleft()\n                levels[level].append(node.val)\n                if node.left:\n                    queue.append(node.left)\n                if node.right:\n                    queue.append(node.right)\n            level += 1\n        return levels","hash":"867b76e194eec4ffd2fdd94aebd8f23ecc3c55f53208dfc58b01d8d7e8671523","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 11-01 Binary Tree Level Order Traversal.py"}]}],"sources":["solutions"]},"topic-day1101combinations":{"key":"topic-day1101combinations","number":null,"title":"Day 11 01 Combinations","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 11-01 Combinations.py","code":"class Solution:\n    def combine(self, n: int, k: int) -> List[List[int]]:\n        result = []\n        def backtrack(startIndex, currentCombination):\n            if len(currentCombination) == k:\n                result.append(list(currentCombination))\n                return\n            for i in range(startIndex, n + 1):\n                currentCombination.append(i)\n                backtrack(i + 1, currentCombination)\n                currentCombination.pop()\n        backtrack(1, [])\n        return result","hash":"acb281eb9ac13ed31aaaa09eaf34d1bb8aefec68e7df2cd1ea853318d73bae1c","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 11-01 Combinations.py"}]}],"sources":["solutions"]},"topic-day1102maximumdepthofbinarytree":{"key":"topic-day1102maximumdepthofbinarytree","number":null,"title":"Day 11 02 Maximum Depth of Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 11-02 Maximum Depth of Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def maxDepth(self, root: Optional[TreeNode]) -> int:\n        return max(self.maxDepth(root.left), self.maxDepth(root.right)) + 1 if root else 0","hash":"cfd834d536c7e28c1dbd241554ef2a9ee386d121d30d9c36ea3100d8c2a2c6d9","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 11-02 Maximum Depth of Binary Tree.py"}]}],"sources":["solutions"]},"topic-day1102permutations":{"key":"topic-day1102permutations","number":null,"title":"Day 11 02 Permutations","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 11-02 Permutations.py","code":"class Solution:\n    def permute(self, nums: List[int]) -> List[List[int]]:\n        numsCapacity, result = len(nums), []\n        def backtrack(startIndex = 0):\n            if startIndex == numsCapacity:\n                result.append(list(nums))\n            for i in range(startIndex, numsCapacity):\n                nums[startIndex], nums[i] = nums[i], nums[startIndex]\n                backtrack(startIndex + 1)\n                nums[startIndex], nums[i] = nums[i], nums[startIndex]\n        backtrack()\n        return result","hash":"45bb2fc6b59500fcd242342b5622b5470093c5ea3b819ffcc210aebaa16f954f","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 11-02 Permutations.py"}]}],"sources":["solutions"]},"topic-day1103lettercasepermutation":{"key":"topic-day1103lettercasepermutation","number":null,"title":"Day 11 03 Letter Case Permutation","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 11-03 Letter Case Permutation.py","code":"class Solution:\n    def letterCasePermutation(self, S: str) -> List[str]:\n        result = [[]]\n        for char in S:\n            n = len(result)\n            if char.isalpha():\n                for i in range(n):\n                    result.append(result[i][:])\n                    result[i].append(char.lower())\n                    result[n + i].append(char.upper())\n            else:\n                for i in range(n):\n                    result[i].append(char)\n        return map(\"\".join, result)","hash":"c809b4eeffaed0a3c8b37a24f8eb490cd8f828606a7d4f841e01a957d0cececd","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 11-03 Letter Case Permutation.py"}]}],"sources":["solutions"]},"topic-day1103symmetrictree":{"key":"topic-day1103symmetrictree","number":null,"title":"Day 11 03 Symmetric Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 11-03 Symmetric Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def isSymmetric(self, root: TreeNode) -> bool:\n        queue = deque([root, root])\n        while queue:\n            node1 = queue.popleft()\n            node2 = queue.popleft()\n            if node1 is None and node2 is None:\n                continue\n            if node1 is None or node2 is None:\n                return False\n            if node1.val != node2.val:\n                return False\n            queue.append(node1.left)\n            queue.append(node2.right)\n            queue.append(node1.right)\n            queue.append(node2.left)\n        return True","hash":"3a8274e437f9ae00e523a04633d58bf0879ff0f5de37c8391b170c7290f708a1","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 11-03 Symmetric Tree.py"}]}],"sources":["solutions"]},"topic-day1201climbingstairs":{"key":"topic-day1201climbingstairs","number":null,"title":"Day 12 01 Climbing Stairs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 12-01 Climbing Stairs.py","code":"class Solution:\n    def climbStairs(self, n: int) -> int:\n        if n == 1:\n            return 1\n        dp = [0, 1, 2]\n        for i in range(3, n + 1):\n            dp.append(dp[i - 1] + dp[i - 2])\n        return dp[n]","hash":"cc3a7d0560a97b5c1acc3cba73ec5febb76cd79a14c05ac2ab8686c188314d5c","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 12-01 Climbing Stairs.py"}]}],"sources":["solutions"]},"topic-day1201invertbinarytree":{"key":"topic-day1201invertbinarytree","number":null,"title":"Day 12 01 Invert Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 12-01 Invert Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def invertTree(self, root: TreeNode) -> TreeNode:\n        if root:\n            root.left, root.right = self.invertTree(root.right), self.invertTree(root.left)\n        return root","hash":"5a2f7acc2212764b2502e9f4ef8d3fb8996417bea0df15b19fe0fa4c4c4b8ebe","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 12-01 Invert Binary Tree.py"}]}],"sources":["solutions"]},"topic-day1202houserobber":{"key":"topic-day1202houserobber","number":null,"title":"Day 12 02 House Robber","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 12-02 House Robber.py","code":"class Solution:\n    def rob(self, nums: List[int]) -> int:\n        prevMax, currMax = 0, 0\n        for num in nums:\n            currMax, prevMax = max(prevMax + num, currMax), currMax\n        return currMax","hash":"8f6b73cd0c7c511d896faf3f7a3542b6130cafcd18b9b698baf4fd7a18a12669","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 12-02 House Robber.py"}]}],"sources":["solutions"]},"topic-day1202pathsum":{"key":"topic-day1202pathsum","number":null,"title":"Day 12 02 Path Sum","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 12-02 Path Sum.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def hasPathSum(self, root: TreeNode, s: int) -> bool:\n        stack = deque([(root, 0)])\n        while stack:\n            node, currentSum = stack.pop()\n            if node is not None:\n                currentSum += node.val\n                if node.left is None and node.right is None:\n                    if currentSum == s:\n                        return True\n                else:\n                    stack.append((node.left, currentSum))\n                    stack.append((node.right, currentSum))\n        return False","hash":"13ff6604d1ae81a76a7473c645355aac98b50c9b88b09e546e4bd45e85428bce","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 12-02 Path Sum.py"}]}],"sources":["solutions"]},"topic-day1203triangle":{"key":"topic-day1203triangle","number":null,"title":"Day 12 03 Triangle","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 12-03 Triangle.py","code":"class Solution:\n    def minimumTotal(self, triangle: List[List[int]]) -> int:\n        if not triangle or not triangle[0]:\n            return 0\n        dp, n = triangle[-1][:], len(triangle)\n        if n == 1:\n            return triangle[0][0]\n        for row in range(n - 2, -1, -1):\n            for col in range(row + 1):\n                dp[col] = min(dp[col], dp[col + 1]) + triangle[row][col]\n        return dp[0]","hash":"3cbf7962e36501c85eda5c04cc64bad70c7b7342bfc61111bfd93d042badfb68","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 12-03 Triangle.py"}]}],"sources":["solutions"]},"topic-day1301poweroftwo":{"key":"topic-day1301poweroftwo","number":null,"title":"Day 13 01 Power of Two","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 13-01 Power of Two.py","code":"class Solution:\n    def isPowerOfTwo(self, n: int) -> bool:\n        if n > 0:\n            return n & (n - 1) == 0\n        return False","hash":"4892ff80fda03ebadf26faf2fc3a658bfa1cd525e3c83da6aab81110082b4de9","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 13-01 Power of Two.py"}]}],"sources":["solutions"]},"topic-day1301searchinabinarysearchtree":{"key":"topic-day1301searchinabinarysearchtree","number":null,"title":"Day 13 01 Search in a Binary Search Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 13-01 Search in a Binary Search Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def searchBST(self, root: Optional[TreeNode], val: int) -> Optional[TreeNode]:\n        if root is None:\n            return root\n        if root.val == val:\n            return root\n        if val < root.val:\n            return self.searchBST(root.left, val)\n        else:\n            return self.searchBST(root.right, val)","hash":"72460585a9c20e1b9bfb0b5025d988614b5c8a431b60d2022d4708c25e8547ae","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 13-01 Search in a Binary Search Tree.py"}]}],"sources":["solutions"]},"topic-day1302insertintoabinarysearchtree":{"key":"topic-day1302insertintoabinarysearchtree","number":null,"title":"Day 13 02 Insert into a Binary Search Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 13-02 Insert into a Binary Search Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def insertIntoBST(self, root: Optional[TreeNode], val: int) -> Optional[TreeNode]:\n        if root is None:\n            return TreeNode(val)\n        if val > root.val:\n            root.right = self.insertIntoBST(root.right, val)\n        else:\n            root.left = self.insertIntoBST(root.left, val)\n        return root","hash":"fb77d16a710a45f5185dc9966252adb770b073279cbac5f8e421fc924b011790","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 13-02 Insert into a Binary Search Tree.py"}]}],"sources":["solutions"]},"topic-day1302numberof1bits":{"key":"topic-day1302numberof1bits","number":null,"title":"Day 13 02 Number of 1 Bits","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 13-02 Number of 1 Bits.py","code":"class Solution:\n    def hammingWeight(self, n: int) -> int:\n        bits, mask = 0, 1\n        for i in range(32):\n            if n & mask != 0:\n                bits += 1\n            mask <<= 1\n        return bits","hash":"36bd9427e510c58611b3ed870f0985dd9aa30271a85e7f18262119ffc45ecb11","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 13-02 Number of 1 Bits.py"}]}],"sources":["solutions"]},"topic-day1401reversebits":{"key":"topic-day1401reversebits","number":null,"title":"Day 14 01 Reverse Bits","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 14-01 Reverse Bits.py","code":"class Solution:\n    def reverseBits(self, n: int) -> int:\n        result = 0\n        for _ in range(32):\n            result = (result << 1) + (n & 1)\n            n >>= 1\n        return result","hash":"c03e40d99a5a4b9553c847950fe87dc084e013e8e974f8b5d4a012790114c5fe","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 14-01 Reverse Bits.py"}]}],"sources":["solutions"]},"topic-day1401validatebinarysearchtree":{"key":"topic-day1401validatebinarysearchtree","number":null,"title":"Day 14 01 Validate Binary Search Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 14-01 Validate Binary Search Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def isValidBST(self, root: TreeNode) -> bool:\n        stack, inorder = deque(), float('-inf')\n        currentNode = root\n        while currentNode or stack:\n            while currentNode:\n                stack.append(currentNode)\n                currentNode = currentNode.left\n            currentNode = stack.pop()\n            if currentNode.val <= inorder:\n                return False\n            inorder = currentNode.val\n            currentNode = currentNode.right\n        return True","hash":"e977108245dcc578df5c239f30d093b9d40c0b07a92cfe311ab8d0ace6a31f85","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 14-01 Validate Binary Search Tree.py"}]}],"sources":["solutions"]},"topic-day1402singlenumber":{"key":"topic-day1402singlenumber","number":null,"title":"Day 14 02 Single Number","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 14-02 Single Number.py","code":"class Solution:\n    def singleNumber(self, nums: List[int]) -> int:\n        result = 0\n        for num in nums:\n            result ^= num\n        return result","hash":"d52ff96ef48b0bddda68a701fd5f909f3c61d45e762dcbca02bab7a3e775b602","origins":[{"source":"solutions","path":"Study Plans/Algorithm I/Day 14-02 Single Number.py"}]}],"sources":["solutions"]},"topic-day1402twosumivinputisabst":{"key":"topic-day1402twosumivinputisabst","number":null,"title":"Day 14 02 Two Sum IV Input is a BST","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 14-02 Two Sum IV - Input is a BST.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def findTarget(self, root: TreeNode, k: int) -> bool:\n        hashSet = set()\n        \n        def find(node):\n            if node is None:\n                return False\n            if k - node.val in hashSet:\n                return True\n            hashSet.add(node.val)\n            return find(node.left) or find(node.right)\n        \n        return find(root)","hash":"d003f62469ced8f38e8b19378da98a7bdefbcc857a0974bb26a55518b94ad1d0","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 14-02 Two Sum IV - Input is a BST.py"}]}],"sources":["solutions"]},"topic-day1403lowestcommonancestorofabinarysearchtree":{"key":"topic-day1403lowestcommonancestorofabinarysearchtree","number":null,"title":"Day 14 03 Lowest Common Ancestor of a Binary Search Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day 14-03 Lowest Common Ancestor of a Binary Search Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, x):\n#         self.val = x\n#         self.left = None\n#         self.right = None\n\nclass Solution:\n    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':\n        node = root\n        while node:\n            if p.val > node.val and q.val > node.val:\n                node = node.right\n            elif p.val < node.val and q.val < node.val:\n                node = node.left\n            else:\n                return node","hash":"f30cfa87e06ddb1ad7fefb559dad6160c9d9ca69114e8714e0054994a4e94237","origins":[{"source":"solutions","path":"Study Plans/Data Structure I/Day 14-03 Lowest Common Ancestor of a Binary Search Tree.py"}]}],"sources":["solutions"]},"topic-dayoftheyear":{"key":"topic-dayoftheyear","number":null,"title":"Day of the Year","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Day of the Year.py","code":"from datetime import datetime\nclass Solution:\n    def dayOfYear(self, date: str) -> int:\n        return datetime(int(date[0:4]), int(date[5:7]), int(date[8:])).timetuple().tm_yday","hash":"61e4c43ae4d219ef91fd58f3d78befa0cdaac9989ba9f9a219ba6a6c5ec4f51d","origins":[{"source":"solutions","path":"Day of the Year.py"}]}],"sources":["solutions"]},"topic-decodestring":{"key":"topic-decodestring","number":null,"title":"Decode String","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Decode String.py","code":"class Solution:\n    def decodeString(self, s: str) -> str:\n        result = ''\n        currentNumber = 0\n        stack = deque()\n        for char in s:\n            if char.isdigit():\n                if currentNumber == 0:\n                    currentNumber = int(char)\n                else:\n                    currentNumber = currentNumber * 10 + int(char)\n            elif char.isalpha():\n                result += char\n            elif char == '[':\n                stack.append((result, currentNumber))\n                result = ''\n                currentNumber = 0\n            elif char == ']':\n                topElement = stack.pop()\n                result = topElement[0] + topElement[1] * result\n        return result","hash":"0fa54cb73cccd112fb07ad67d9cad13f3d76b5b58c03316bc555881e73817ba6","origins":[{"source":"solutions","path":"Google Interview Questions/Decode String.py"}]},{"language":"python","name":"Decode String.py","code":"class Solution:\n    def decodeString(self, s: str) -> str:\n        result, stack, currentCount = '', deque(), ''\n        for char in s:\n            if char.isdigit():\n                currentCount += char\n            elif char.isalpha():\n                result += char\n            elif char == '[':\n                stack.append((result, int(currentCount)))\n                result, currentCount = '', ''\n            elif char == ']':\n                oldResult, count = stack.pop()\n                result = oldResult + count * result\n        return result","hash":"75b9b362bb2593e7192e391334973fa16df2b097942312efc0f3032a38c2170b","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-11 Leetcoding Challenge/Decode String.py"}]}],"sources":["solutions"]},"topic-decodewaysii":{"key":"topic-decodewaysii","number":null,"title":"Decode Ways II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Decode Ways II.py","code":"class Solution:\n    def numDecodings(self, s: str) -> int:\n        M = 10 ** 9 + 7\n        first, second = 1, 9 if s[0] == '*' else 0 if s[0] == '0' else 1\n        for i in range(1, len(s)):\n            temp = second\n            if s[i] == '*':\n                second = (9 * second) % M\n                if s[i - 1] == '1':\n                    second = (second + 9 * first) % M\n                elif s[i - 1] == '2':\n                    second = (second + 6 * first) % M\n                elif s[i - 1] == '*':\n                    second = (second + 15 * first) % M\n            else:\n                second = second if s[i] != '0' else 0\n                if s[i - 1] == '1':\n                    second = (second + first) % M\n                elif s[i - 1] == '2' and s[i] <= '6':\n                    second = (second + first) % M\n                elif s[i - 1] == '*':\n                    second = (second + (2 if s[i] <= '6' else 1) * first) % M\n            first = temp\n        return second","hash":"1d4c557c3a077a83a14b9974505cbc07a60c6a3399fd7497d216b741b8d0ce25","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-07 Leetcoding Challenge/Decode Ways II.py"}]}],"sources":["solutions"]},"topic-decompressrunlengthencodedlist":{"key":"topic-decompressrunlengthencodedlist","number":null,"title":"Decompress Run Length Encoded List","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Decompress Run-Length Encoded List.py","code":"class Solution:\n    def decompressRLElist(self, nums: List[int]) -> List[int]:\n        result = []\n        for i in range(0, len(nums), 2):\n            result.extend([nums[i + 1]] * nums[i])\n        return result","hash":"975bbe3bd018963290f8006cc39b78efb479531792075d07fb78c173080970ca","origins":[{"source":"solutions","path":"Decompress Run-Length Encoded List.py"}]}],"sources":["solutions"]},"topic-deepestleavessum":{"key":"topic-deepestleavessum","number":null,"title":"Deepest Leaves Sum","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Deepest Leaves Sum.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def deepestLeavesSum(self, root: TreeNode) -> int:\n        nextLevel = deque([root,])\n        while nextLevel:\n            currentLevel, nextLevel = nextLevel, deque()\n            for node in currentLevel:\n                if node.left:\n                    nextLevel.append(node.left)\n                if node.right:\n                    nextLevel.append(node.right)\n        return sum([node.val for node in currentLevel])","hash":"22dae559941a8a3b8207dcf1fea14cda186be188ca788b623ee51147a177ba3d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-04 Leetcoding Challenge/Deepest Leaves Sum.py"}]},{"language":"python","name":"Deepest Leaves Sum.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def deepestLeavesSum(self, root: Optional[TreeNode]) -> int:\n        nextLevel = deque([root,])\n        while nextLevel:\n            currentLevel, nextLevel = nextLevel, deque()\n            for node in currentLevel:\n                if node.left:\n                    nextLevel.append(node.left)\n                if node.right:\n                    nextLevel.append(node.right)\n        return sum([node.val for node in currentLevel])","hash":"a1e9682a7212e1a3c05af51c1d10154a891d000a0f40085c82c11b217d4f04d8","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-05 Leetcoding Challenge/Deepest Leaves Sum.py"}]}],"sources":["solutions"]},"topic-defanginganipaddress":{"key":"topic-defanginganipaddress","number":null,"title":"Defanging an IP Address","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Defanging an IP Address.py","code":"class Solution:\n    def defangIPaddr(self, address: str) -> str:\n        return address.replace('.', '[.]')","hash":"e547411b89a60bcf300b0741ad6ea5686965f2c40e3d716d0c293da15ad29d4c","origins":[{"source":"solutions","path":"Defanging an IP Address.py"}]}],"sources":["solutions"]},"topic-degreeofanarray":{"key":"topic-degreeofanarray","number":null,"title":"Degree of an Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Degree of an Array.py","code":"class Solution:\n    def findShortestSubArray(self, nums: List[int]) -> int:\n        leftIndexMap, rightIndexMap, countMap = {}, {}, {}\n        for i, num in enumerate(nums):\n            if num not in leftIndexMap:\n                leftIndexMap[num] = i\n            rightIndexMap[num] = i\n            countMap[num] = countMap.get(num, 0) + 1\n        result = len(nums)\n        maxDegree = max(countMap.values())\n        for num in countMap:\n            if countMap[num] == maxDegree:\n                result = min(result, rightIndexMap[num] - leftIndexMap[num] + 1)\n        return result","hash":"e488751e2c930a7e8927f0af32bb94923062c6eab14cbd7f3a565434465e8249","origins":[{"source":"solutions","path":"Degree of an Array.py"}]}],"sources":["solutions"]},"topic-deleteandearn":{"key":"topic-deleteandearn","number":null,"title":"Delete and Earn","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Delete and Earn.py","code":"class Solution:\n    def deleteAndEarn(self, nums: List[int]) -> int:\n        points, maxNumber = defaultdict(int), 0\n        # Precompute how many points we gain from taking an element\n        for num in nums:\n            points[num] += num\n            maxNumber = max(maxNumber, num)\n        @cache\n        def maxPoints(num):\n            # Check for base cases\n            if num == 0:\n                return 0\n            if num == 1:\n                return points[1]\n            # Apply recurrence relation\n            return max(maxPoints(num - 1), maxPoints(num - 2) + points[num])\n        return maxPoints(maxNumber)","hash":"c664f4e9a11af5959bd76c426e42b9f7d1a0539a4d8b5994b0764d69c17065a9","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-03 Leetcoding Challenge/Delete and Earn.py"}]}],"sources":["solutions"]},"topic-deletecolumnstomakesorted":{"key":"topic-deletecolumnstomakesorted","number":null,"title":"Delete Columns to Make Sorted","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Delete Columns to Make Sorted.py","code":"class Solution:\n    def minDeletionSize(self, strs: List[str]) -> int:\n        return sum([list(s) != sorted(s) for s in zip(*strs)])","hash":"2aab4a8cb7c1628bab5aa034bdc4a716fdd9902109ada6b8e1514d356ff2c086","origins":[{"source":"solutions","path":"Delete Columns to Make Sorted.py"},{"source":"solutions","path":"LeetCoding Challenges/2023/2023-01 Leetcoding Challenge/Delete Columns to Make Sorted.py"}]}],"sources":["solutions"]},"topic-deleteleaveswithagivenvalue":{"key":"topic-deleteleaveswithagivenvalue","number":null,"title":"Delete Leaves With a Given Value","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Delete Leaves With a Given Value.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def removeLeafNodes(self, root: TreeNode, target: int) -> TreeNode:\n        def isLeaf(node):\n            return node.left is None and node.right is None\n        def helper(node):\n            if isLeaf(node):\n                if node.val == target:\n                    return None\n                else:\n                    return node\n            else:\n                if node.left:\n                    node.left = helper(node.left)\n                if node.right:\n                    node.right = helper(node.right)\n                if isLeaf(node) and node.val == target:\n                    return None\n                return node\n        if root is None:\n            return root\n        return helper(root)","hash":"d3509e7505afb795a27161912d450a160b2542718e479f0414812d96da4ec486","origins":[{"source":"solutions","path":"Delete Leaves With a Given Value.py"}]}],"sources":["solutions"]},"topic-deletenodeinabst":{"key":"topic-deletenodeinabst","number":null,"title":"Delete Node in a BST","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Delete Node in a BST.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    \n    def _successorValue(self, node):\n        node = node.right\n        while node.left:\n            node = node.left\n        return node.val\n    \n    def _predecessorValue(self, node):\n        node = node.left\n        while node.right:\n            node = node.right\n        return node.val\n        \n    def deleteNode(self, root: TreeNode, key: int) -> TreeNode:\n        if root is None:\n            return None\n        if key > root.val:\n            root.right = self.deleteNode(root.right, key)\n        elif key < root.val:\n            root.left = self.deleteNode(root.left, key)\n        else:\n            if root.left is None and root.right is None:\n                root = None\n            elif root.right:\n                successorValue = self._successorValue(root)\n                root.val = successorValue\n                root.right = self.deleteNode(root.right, successorValue)\n            else:\n                predecessorValue = self._predecessorValue(root)\n                root.val = predecessorValue\n                root.left = self.deleteNode(root.left, predecessorValue)\n        return root","hash":"8db514277d6f9231291878371be10cda549e7dec2039699b18beb918b1d4e7bb","origins":[{"source":"solutions","path":"Binary Search Tree/Delete Node in a BST.py"},{"source":"solutions","path":"LeetCoding Challenges/2020/2020-08 Leetcoding Challenge/Delete Node in a BST.py"}]}],"sources":["solutions"]},"topic-deletenodesandreturnforest":{"key":"topic-deletenodesandreturnforest","number":null,"title":"Delete Nodes and Return Forest","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Delete Nodes and Return Forest.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def delNodes(self, root: TreeNode, to_delete: List[int]) -> List[TreeNode]:\n        result = []\n        def removeNodes(node, toDelete, parentExists = False):\n            nonlocal result\n            if node is None:\n                return None\n            if node.val in toDelete:\n                node.left = removeNodes(node.left, toDelete)\n                node.right = removeNodes(node.right, toDelete)\n                return None\n            else:\n                if not parentExists:\n                    result.append(node)\n                node.left = removeNodes(node.left, toDelete, True)\n                node.right = removeNodes(node.right, toDelete, True)\n                return node\n        removeNodes(root, to_delete)\n        return result","hash":"9bfbbb1dad4940954b8508710e4d0de0f9e171f883ef482775ef41ac847f3144","origins":[{"source":"solutions","path":"Mock Interviews/Google/Phone Interview 08/Delete Nodes and Return Forest.py"}]}],"sources":["solutions"]},"algorithm-depth-first-search":{"key":"algorithm-depth-first-search","number":null,"title":"depth first search","difficulty":"Unknown","tags":["Algorithm Reference"],"documents":[],"sources":["algorithms"],"solutions":[{"language":"python","name":"depth_first_search.py","code":"\"\"\"Non recursive implementation of a DFS algorithm.\"\"\"\n\nfrom __future__ import annotations\n\n\ndef depth_first_search(graph: dict, start: str) -> set[str]:\n    \"\"\"Depth First Search on Graph\n    :param graph: directed graph in dictionary format\n    :param start: starting vertex as a string\n    :returns: the trace of the search\n    >>> input_G = { \"A\": [\"B\", \"C\", \"D\"], \"B\": [\"A\", \"D\", \"E\"],\n    ... \"C\": [\"A\", \"F\"], \"D\": [\"B\", \"D\"], \"E\": [\"B\", \"F\"],\n    ... \"F\": [\"C\", \"E\", \"G\"], \"G\": [\"F\"] }\n    >>> output_G = list({'A', 'B', 'C', 'D', 'E', 'F', 'G'})\n    >>> all(x in output_G for x in list(depth_first_search(input_G, \"A\")))\n    True\n    >>> all(x in output_G for x in list(depth_first_search(input_G, \"G\")))\n    True\n    \"\"\"\n    explored, stack = set(start), [start]\n\n    while stack:\n        v = stack.pop()\n        explored.add(v)\n        # Differences from BFS:\n        # 1) pop last element instead of first one\n        # 2) add adjacent elements to stack without exploring them\n        for adj in reversed(graph[v]):\n            if adj not in explored:\n                stack.append(adj)\n    return explored\n\n\nG = {\n    \"A\": [\"B\", \"C\", \"D\"],\n    \"B\": [\"A\", \"D\", \"E\"],\n    \"C\": [\"A\", \"F\"],\n    \"D\": [\"B\", \"D\"],\n    \"E\": [\"B\", \"F\"],\n    \"F\": [\"C\", \"E\", \"G\"],\n    \"G\": [\"F\"],\n}\n\nif __name__ == \"__main__\":\n    import doctest\n\n    doctest.testmod()\n    print(depth_first_search(G, \"A\"))\n","hash":"4b317eacddc72e6467f48ad87a07c3e8442e02d12740469d6cce43f7984b87e6","origins":[{"source":"algorithms","path":"graphs/depth_first_search.py","url":"https://github.com/TheAlgorithms/Python/blob/25c712f2692449e91a57748d328ef34fccf25654/graphs/depth_first_search.py","commit":"25c712f2692449e91a57748d328ef34fccf25654"}]}]},"topic-describethepainting":{"key":"topic-describethepainting","number":null,"title":"Describe the Painting","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Describe the Painting.py","code":"class Solution:\n    def splitPainting(self, segments: List[List[int]]) -> List[List[int]]:\n        colorMap = defaultdict(int)\n        for start, end, color in segments:\n            colorMap[start] += color\n            colorMap[end] -= color\n        result, prev, color = [], None, 0\n        for now in sorted(colorMap):\n            if color:\n                result.append((prev, now, color))\n            color += colorMap[now]\n            prev = now\n        return result","hash":"5035f39da61c7ef7d0f8fd135a83b4999fc810c378a286d301c20a4c4dc77521","origins":[{"source":"solutions","path":"Describe the Painting.py"}]}],"sources":["solutions"]},"topic-designatexteditor":{"key":"topic-designatexteditor","number":null,"title":"Design a Text Editor","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Design a Text Editor.py","code":"class TextEditor:\n\n    def __init__(self):\n        self.left, self.right = [], []\n\n    def addText(self, text: str) -> None:\n        self.left.extend(text)\n\n    def deleteText(self, k: int) -> int:\n        count = 0\n        while self.left and count < k:\n            self.left.pop()\n            count += 1\n        return count\n\n    def cursorLeft(self, k: int) -> str:\n        count = 0\n        while self.left and count < k:\n            self.right.append(self.left.pop())\n            count += 1\n        return ''.join(self.left[max(-10, -len(self.left)):])\n\n    def cursorRight(self, k: int) -> str:\n        count = 0\n        while self.right and count < k:\n            self.left.append(self.right.pop())\n            count += 1\n        return ''.join(self.left[max(-10, -len(self.left)):])\n\n\n# Your TextEditor object will be instantiated and called as such:\n# obj = TextEditor()\n# obj.addText(text)\n# param_2 = obj.deleteText(k)\n# param_3 = obj.cursorLeft(k)\n# param_4 = obj.cursorRight(k)","hash":"07bd9d953de022b9860353d11c6811a3dbd4347543825ccb7161daf574d4e29b","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-08 Leetcoding Challenge/Design a Text Editor.py"}]}],"sources":["solutions"]},"topic-designaddandsearchwordsdatastructure":{"key":"topic-designaddandsearchwordsdatastructure","number":null,"title":"Design Add and Search Words Data Structure","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Design Add and Search Words Data Structure.py","code":"class TrieNode:\n    \n    def __init__(self):\n        self.childNodes = {}\n        self.isEnd = False\n\nclass WordDictionary:\n\n    def __init__(self):\n        self.root = TrieNode()\n\n    def addWord(self, word: str) -> None:\n        node = self.root\n        for c in word:\n            n = node.childNodes.get(c, TrieNode())\n            node.childNodes[c] = n\n            node = n\n        node.isEnd = True\n\n    def search(self, word: str) -> bool:\n        return self._searchHelper(word, self.root)\n    \n    def _searchHelper(self, word: str, node: TrieNode):\n        for index, c in enumerate(word):\n            if c == '.':\n                for char, childNode in node.childNodes.items():\n                    if self._searchHelper(word[index + 1:], childNode):\n                        return True\n                return False\n            else:\n                node = node.childNodes.get(c)\n                if not node:\n                    return False\n        return node.isEnd\n\n\n# Your WordDictionary object will be instantiated and called as such:\n# obj = WordDictionary()\n# obj.addWord(word)\n# param_2 = obj.search(word)","hash":"91ae5caeadc33bf3757d716e86fb9aae4f27265252cbcd3d09187aff4c090cf9","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-01 LeetCoding Challenge/Design Add and Search Words Data Structure.py"},{"source":"solutions","path":"LeetCoding Challenges/2023/2023-03 Leetcoding Challenge/Design Add and Search Words Data Structure.py"}]}],"sources":["solutions"]},"topic-designanatmmachine":{"key":"topic-designanatmmachine","number":null,"title":"Design an ATM Machine","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Design an ATM Machine.py","code":"class ATM:\n\n    def __init__(self):\n        self.denominations, self.value = [0] * 5, {0: 20, 1: 50, 2: 100, 3: 200, 4: 500}\n\n    def deposit(self, banknotesCount: List[int]) -> None:\n        for index, count in enumerate(banknotesCount):\n            self.denominations[index] += count\n\n    def withdraw(self, amount: int) -> List[int]:\n        result = [0] * 5\n        for index in range(4, -1, -1):\n            requiredCount = min(amount // self.value[index], self.denominations[index])\n            result[index] += requiredCount\n            amount -= (requiredCount * self.value[index])\n        if amount == 0:\n            for index in range(5):\n                self.denominations[index] -= result[index]\n            return result\n        return [-1]\n\n\n# Your ATM object will be instantiated and called as such:\n# obj = ATM()\n# obj.deposit(banknotesCount)\n# param_2 = obj.withdraw(amount)","hash":"b0e4c10bbaf28bd6ce8409d49415e148969800b525c9f4fe8f0ed860b2fc9dc4","origins":[{"source":"solutions","path":"Design an ATM Machine.py"}]}],"sources":["solutions"]},"topic-designanorderedstream":{"key":"topic-designanorderedstream","number":null,"title":"Design an Ordered Stream","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Design an Ordered Stream.py","code":"class OrderedStream:\n\n    def __init__(self, n: int):\n        self.stream, self.ptr, self.capacity = defaultdict(str), 1, n\n\n    def insert(self, idKey: int, value: str) -> List[str]:\n        self.stream[idKey], currentPtr, result = value, self.ptr, []\n        while self.stream[currentPtr] and self.ptr <= currentPtr <= self.capacity:\n            result.append(self.stream[currentPtr])\n            currentPtr += 1\n        self.ptr = currentPtr\n        return result\n\n\n# Your OrderedStream object will be instantiated and called as such:\n# obj = OrderedStream(n)\n# param_1 = obj.insert(idKey,value)","hash":"e9c0d69f50034a8802700b4606f0da28377157b55a5645c211164ec72a70c2c7","origins":[{"source":"solutions","path":"Design an Ordered Stream.py"}]}],"sources":["solutions"]},"topic-designboundedblockingqueue":{"key":"topic-designboundedblockingqueue","number":null,"title":"Design Bounded Blocking Queue","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Design Bounded Blocking Queue.py","code":"from threading import Semaphore\n\nclass BoundedBlockingQueue(object):\n\n    def __init__(self, capacity: int):\n        self.emptySlots = Semaphore(capacity)\n        self.occupiedSlots = Semaphore(0)\n        self.queue = deque()\n\n    def enqueue(self, element: int) -> None:\n        self.emptySlots.acquire()\n        self.queue.append(element)\n        self.occupiedSlots.release()\n\n    def dequeue(self) -> int:\n        self.occupiedSlots.acquire()\n        element = self.queue.popleft()\n        self.emptySlots.release()\n        return element\n\n    def size(self) -> int:\n        return len(self.queue)","hash":"474de4462ae31dd9c64aa588e5c4251b77267a6aa7f3cc121e9e611c84c3dbb2","origins":[{"source":"solutions","path":"Design Bounded Blocking Queue.py"}]}],"sources":["solutions"]},"topic-designbrowserhistory":{"key":"topic-designbrowserhistory","number":null,"title":"Design Browser History","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Design Browser History.py","code":"class BrowserHistory:\n\n    def __init__(self, homepage: str):\n        self.currentIndex = 0\n        self.maxIndex = 0\n        self.history = {self.currentIndex: homepage}\n\n    def visit(self, url: str) -> None:\n        self.currentIndex += 1\n        self.history[self.currentIndex] = url\n        self.maxIndex = self.currentIndex\n\n    def back(self, steps: int) -> str:\n        self.currentIndex -= steps\n        self.currentIndex = 0 if self.currentIndex < 0 else self.currentIndex\n        return self.history[self.currentIndex]\n\n    def forward(self, steps: int) -> str:\n        self.currentIndex += steps\n        self.currentIndex = self.maxIndex if self.currentIndex > self.maxIndex else self.currentIndex\n        return self.history[self.currentIndex]\n\n\n# Your BrowserHistory object will be instantiated and called as such:\n# obj = BrowserHistory(homepage)\n# obj.visit(url)\n# param_2 = obj.back(steps)\n# param_3 = obj.forward(steps)","hash":"217137ee1017be7bf3d9c6732c71d3372e976f8bfa7a9623fd6e407ba4b79241","origins":[{"source":"solutions","path":"Design Browser History.py"},{"source":"solutions","path":"LeetCoding Challenges/2023/2023-03 Leetcoding Challenge/Design Browser History.py"}]}],"sources":["solutions"]},"topic-designdoublylinkedlist":{"key":"topic-designdoublylinkedlist","number":null,"title":"Design Doubly Linked List","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Design Doubly Linked List.py","code":"class ListNode:\n    \n    def __init__(self, val = None, nextNode = None, prevNode = None):\n        self.val = val\n        self.next = nextNode\n        self.prev = prevNode\n\nclass MyLinkedList:\n\n    def __init__(self):\n        \"\"\"\n        Initialize your data structure here.\n        \"\"\"\n        self.head, self.tail = ListNode(0), ListNode(0)\n        self.size = 0\n        self.head.next = self.tail\n        self.tail.prev = self.head\n\n    def get(self, index: int) -> int:\n        \"\"\"\n        Get the value of the index-th node in the linked list. If the index is invalid, return -1.\n        \"\"\"\n        if index < 0 or index >= self.size:\n            return -1\n        if index + 1 < self.size - index:\n            currentNode = self.head\n            for _ in range(index + 1):\n                currentNode = currentNode.next\n            return currentNode.val\n        else:\n            currentNode = self.tail\n            for _ in range(self.size - index):\n                currentNode = currentNode.prev\n            return currentNode.val\n\n    def addAtHead(self, val: int) -> None:\n        \"\"\"\n        Add a node of value val before the first element of the linked list. After the insertion, the new node will be the first node of the linked list.\n        \"\"\"\n        predecessor, successor = self.head, self.head.next\n        self.size += 1\n        newNode = ListNode(val)\n        newNode.next = successor\n        newNode.prev = predecessor\n        predecessor.next = newNode\n        successor.prev = newNode\n\n    def addAtTail(self, val: int) -> None:\n        \"\"\"\n        Append a node of value val to the last element of the linked list.\n        \"\"\"\n        predecessor, successor = self.tail.prev, self.tail\n        self.size += 1\n        newNode = ListNode(val)\n        newNode.next = successor\n        newNode.prev = predecessor\n        predecessor.next = newNode\n        successor.prev = newNode\n\n    def addAtIndex(self, index: int, val: int) -> None:\n        \"\"\"\n        Add a node of value val before the index-th node in the linked list. If index equals to the length of linked list, the node will be appended to the end of linked list. If index is greater than the length, the node will not be inserted.\n        \"\"\"\n        if index > self.size:\n            return\n        if index < 0:\n            index = 0\n        if index < self.size - index:\n            predecessor = self.head\n            for _ in range(index):\n                predecessor = predecessor.next\n            successor = predecessor.next\n        else:\n            successor = self.tail\n            for _ in range(self.size - index):\n                successor = successor.prev\n            predecessor = successor.prev\n        self.size += 1\n        newNode = ListNode(val)\n        newNode.next = successor\n        newNode.prev = predecessor\n        predecessor.next = newNode\n        successor.prev = newNode\n\n    def deleteAtIndex(self, index: int) -> None:\n        \"\"\"\n        Delete the index-th node in the linked list, if the index is valid.\n        \"\"\"\n        if index < 0 or index >= self.size:\n            return\n        if index < self.size - index:\n            predecessor = self.head\n            for _ in range(index):\n                predecessor = predecessor.next\n            successor = predecessor.next.next\n        else:\n            successor = self.tail\n            for _ in range(self.size - index - 1):\n                successor = successor.prev\n            predecessor = successor.prev.prev\n        self.size -= 1\n        predecessor.next = successor\n        successor.prev = predecessor\n\n# Your MyLinkedList object will be instantiated and called as such:\n# obj = MyLinkedList()\n# param_1 = obj.get(index)\n# obj.addAtHead(val)\n# obj.addAtTail(val)\n# obj.addAtIndex(index,val)\n# obj.deleteAtIndex(index)","hash":"c220ced0516d06f5459db052e4ef5b79e20bb1393ec16182c09d1d5bfcf886e5","origins":[{"source":"solutions","path":"Linked List/Design Doubly Linked List.py"}]}],"sources":["solutions"]},"topic-designfilesystem":{"key":"topic-designfilesystem","number":null,"title":"Design File System","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Design File System.py","code":"class FileSystem:\n\n    def __init__(self):\n        self.fileSystem = {}\n        self.endToken = '#'\n\n    def createPath(self, path: str, value: int) -> bool:\n        if path in {'', '/'}:\n            return False\n        if path.startswith('/'):\n            tokens = path.split('/')[1:]\n            currentNode = self.fileSystem\n            for i, token in enumerate(tokens, 1):\n                if token not in currentNode:\n                    if i != len(tokens):\n                        return False\n                    else:\n                        currentNode[token] = {self.endToken: value}\n                        return True\n                else:\n                    currentNode = currentNode[token]\n        return False\n\n    def get(self, path: str) -> int:\n        if path in {'', '/'}:\n            return -1\n        if path.startswith('/'):\n            tokens = path.split('/')[1:]\n            currentNode = self.fileSystem\n            for i, token in enumerate(tokens, 1):\n                if token not in currentNode:\n                    return -1\n                else:\n                    currentNode = currentNode[token]\n                    if i == len(tokens) and self.endToken in currentNode:\n                        return currentNode[self.endToken]\n        return -1\n\n# Your FileSystem object will be instantiated and called as such:\n# obj = FileSystem()\n# param_1 = obj.createPath(path,value)\n# param_2 = obj.get(path)","hash":"e1147adbdbdd849603cb8b9eccdec71f413307fcafc71d448ab4de6fdc273d85","origins":[{"source":"solutions","path":"Design File System.py"}]}],"sources":["solutions"]},"topic-designhashmap":{"key":"topic-designhashmap","number":null,"title":"Design Hash Map","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Design HashMap.py","code":"class MyHashMap:\n\n    def __init__(self):\n        \"\"\"\n        Initialize your data structure here.\n        \"\"\"\n        self.hashMap = dict()\n\n    def put(self, key: int, value: int) -> None:\n        \"\"\"\n        value will always be non-negative.\n        \"\"\"\n        self.hashMap[key] = value\n\n    def get(self, key: int) -> int:\n        \"\"\"\n        Returns the value to which the specified key is mapped, or -1 if this map contains no mapping for the key\n        \"\"\"\n        return self.hashMap.get(key, -1)\n\n    def remove(self, key: int) -> None:\n        \"\"\"\n        Removes the mapping of the specified value key if this map contains a mapping for the key\n        \"\"\"\n        if key in self.hashMap:\n            del self.hashMap[key]\n\n\n# Your MyHashMap object will be instantiated and called as such:\n# obj = MyHashMap()\n# obj.put(key,value)\n# param_2 = obj.get(key)\n# obj.remove(key)","hash":"7dd7d92b41641c48cc70732760a4f895da733d6cdd905edf50b4fbf742d3c3b6","origins":[{"source":"solutions","path":"Hash Table/Design HashMap.py"},{"source":"solutions","path":"LeetCoding Challenges/2021/2021-03 Leetcoding Challenge/Design HashMap.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-04 Leetcoding Challenge/Design HashMap.py"}]}],"sources":["solutions"]},"topic-designlinkedlist":{"key":"topic-designlinkedlist","number":null,"title":"Design Linked List","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Design Linked List.py","code":"class Node:\n    \n    def __init__(self, val=0):\n        self.val = val\n        self.next = None\n\nclass MyLinkedList:\n\n    def __init__(self):\n        \"\"\"\n        Initialize your data structure here.\n        \"\"\"\n        self.size = 0\n        self.head = Node(0)\n\n    def get(self, index: int) -> int:\n        \"\"\"\n        Get the value of the index-th node in the linked list. If the index is invalid, return -1.\n        \"\"\"\n        if index < 0 or index >= self.size:\n            return -1\n        curr = self.head\n        for _ in range(index + 1):\n            curr = curr.next\n        return curr.val\n\n    def addAtHead(self, val: int) -> None:\n        \"\"\"\n        Add a node of value val before the first element of the linked list. After the insertion, the new node will be the first node of the linked list.\n        \"\"\"\n        self.addAtIndex(0, val)\n        \n    def addAtTail(self, val: int) -> None:\n        \"\"\"\n        Append a node of value val to the last element of the linked list.\n        \"\"\"\n        self.addAtIndex(self.size, val)\n\n    def addAtIndex(self, index: int, val: int) -> None:\n        \"\"\"\n        Add a node of value val before the index-th node in the linked list. If index equals to the length of linked list, the node will be appended to the end of linked list. If index is greater than the length, the node will not be inserted.\n        \"\"\"\n        if index > self.size:\n            return\n        if index < 0:\n            index = 0\n        self.size += 1\n        pred = self.head\n        for _ in range(index):\n            pred = pred.next\n        newNode = Node(val)\n        newNode.next = pred.next\n        pred.next = newNode\n\n    def deleteAtIndex(self, index: int) -> None:\n        \"\"\"\n        Delete the index-th node in the linked list, if the index is valid.\n        \"\"\"\n        if index < 0 or index >= self.size:\n            return\n        self.size -= 1\n        pred = self.head\n        for _ in range(index):\n            pred = pred.next\n        pred.next = pred.next.next\n\n# Your MyLinkedList object will be instantiated and called as such:\n# obj = MyLinkedList()\n# param_1 = obj.get(index)\n# obj.addAtHead(val)\n# obj.addAtTail(val)\n# obj.addAtIndex(index,val)\n# obj.deleteAtIndex(index)","hash":"7e7ec14886bdc6136081817d65e9cb260858518cffa52b1ff7474b136790098d","origins":[{"source":"solutions","path":"Linked List/Design Linked List.py"}]}],"sources":["solutions"]},"topic-designmovierentalsystem":{"key":"topic-designmovierentalsystem","number":null,"title":"Design Movie Rental System","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Design Movie Rental System.py","code":"from sortedcontainers import SortedList\n\nclass MovieRentingSystem:\n\n    def __init__(self, n: int, entries: List[List[int]]):\n        self.SEARCH_RESULT_COUNT, self.REPORT_RESULT_COUNT = 5, 5\n        self._getPrice = defaultdict(lambda : defaultdict(int))\n        self._searchList = defaultdict(SortedList)\n        self._rentedList = SortedList()\n        for shop, movie, price in entries:\n            self._getPrice[shop][movie] = price\n            self._searchList[movie].add((price, shop))\n\n    def search(self, movie: int) -> List[int]:\n        return [data[1] for data in self._searchList[movie][:self.SEARCH_RESULT_COUNT]]\n\n    def rent(self, shop: int, movie: int) -> None:\n        price = self._getPrice[shop][movie]\n        self._searchList[movie].remove((price, shop))\n        self._rentedList.add((price, shop, movie))\n\n    def drop(self, shop: int, movie: int) -> None:\n        price = self._getPrice[shop][movie]\n        self._searchList[movie].add((price, shop))\n        self._rentedList.remove((price, shop, movie))\n\n    def report(self) -> List[List[int]]:\n        return [[data[1], data[2]] for data in self._rentedList[:self.REPORT_RESULT_COUNT]]\n\n\n# Your MovieRentingSystem object will be instantiated and called as such:\n# obj = MovieRentingSystem(n, entries)\n# param_1 = obj.search(movie)\n# obj.rent(shop,movie)\n# obj.drop(shop,movie)\n# param_4 = obj.report()","hash":"2e75a45e3804ce1ce688585e8b422f33d66f160389355d699bed9ac26250f7fe","origins":[{"source":"solutions","path":"Design Movie Rental System.py"}]}],"sources":["solutions"]},"topic-designsearchautocompletesystem":{"key":"topic-designsearchautocompletesystem","number":null,"title":"Design Search Autocomplete System","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Design Search Autocomplete System.py","code":"class TrieNode:\n    \n    def __init__(self, string = '', times = 0):\n        self.string = string\n        self.times = times\n        self.children = defaultdict(TrieNode)\n\nclass AutocompleteSystem:\n\n    def __init__(self, sentences: List[str], times: List[int]):\n        self.root = TrieNode()\n        self.currentString = ''\n        for sentence, frequency in zip(sentences, times):\n            self.__insert(self.root, sentence, frequency)\n    \n    def __insert(self, currentNode, sentence, frequency):\n        for char in sentence:\n            currentNode = currentNode.children.setdefault(char, TrieNode(char))\n        currentNode.times += frequency\n        \n    def __lookup(self, currentNode, string):\n        for char in string:\n            if char not in currentNode.children:\n                return []\n            currentNode = currentNode.children[char]\n        matchingStrings = []\n        self.__traverse(currentNode, string, matchingStrings)\n        return matchingStrings\n    \n    def __traverse(self, currentNode, string, matchingStrings):\n        if currentNode.times > 0:\n            matchingStrings.append((string, currentNode.times))\n        for key in currentNode.children:\n            self.__traverse(currentNode.children[key], string + key, matchingStrings)\n\n    def input(self, c: str) -> List[str]:\n        if c == '#':\n            self.__insert(self.root, self.currentString, 1)\n            self.currentString = ''\n        else:\n            self.currentString += c\n            listOfTuple = self.__lookup(self.root, self.currentString)\n            listOfTuple.sort(key = lambda x : (-1 * x[1], x[0]))\n            result = []\n            numberOfResults = 0\n            for Tuple in listOfTuple:\n                result.append(Tuple[0])\n                numberOfResults += 1\n                if numberOfResults >= 3:\n                    break\n            return result\n\n\n# Your AutocompleteSystem object will be instantiated and called as such:\n# obj = AutocompleteSystem(sentences, times)\n# param_1 = obj.input(c)","hash":"1efa4b295583bb6a5ba221a073757a70c57df61c32374f916c3bcb81d03507a4","origins":[{"source":"solutions","path":"Trie/Design Search Autocomplete System.py"}]}],"sources":["solutions"]},"topic-designtwitter":{"key":"topic-designtwitter","number":null,"title":"Design Twitter","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Design Twitter.py","code":"class Twitter:\n\n    def __init__(self):\n        \"\"\"\n        Initialize your data structure here.\n        \"\"\"\n        self.time = 0\n        self.tweetsMap = defaultdict(deque)\n        self.followersMap = defaultdict(set)\n\n    def postTweet(self, userId: int, tweetId: int) -> None:\n        \"\"\"\n        Compose a new tweet.\n        \"\"\"\n        self.tweetsMap[userId].appendleft((self.time, tweetId))\n        self.time += 1\n\n    def getNewsFeed(self, userId: int) -> List[int]:\n        \"\"\"\n        Retrieve the 10 most recent tweet ids in the user's news feed. Each item in the news feed must be posted by users who the user followed or by the user herself. Tweets must be ordered from most recent to least recent.\n        \"\"\"\n        maxHeap, newsFeed = [], []\n        if len(self.tweetsMap[userId]) > 0:\n            time, tweetId = self.tweetsMap[userId][0]\n            heappush(maxHeap, (-1 * time, tweetId, userId, 0))\n        for follower in self.followersMap[userId]:\n            if len(self.tweetsMap[follower]) > 0:\n                time, tweetId = self.tweetsMap[follower][0]\n                heappush(maxHeap, (-1 * time, tweetId, follower, 0))\n        for _ in range(10):\n            if not maxHeap:\n                break\n            time, tweetId, userId, index = heappop(maxHeap)\n            newsFeed.append(tweetId)\n            if index + 1 < len(self.tweetsMap[userId]):\n                time, tweetId = self.tweetsMap[userId][index + 1]\n                heappush(maxHeap, (-1 * time, tweetId, userId, index + 1))\n        return newsFeed\n\n    def follow(self, followerId: int, followeeId: int) -> None:\n        \"\"\"\n        Follower follows a followee. If the operation is invalid, it should be a no-op.\n        \"\"\"\n        if followerId != followeeId:\n            self.followersMap[followerId].add(followeeId)\n\n    def unfollow(self, followerId: int, followeeId: int) -> None:\n        \"\"\"\n        Follower unfollows a followee. If the operation is invalid, it should be a no-op.\n        \"\"\"\n        self.followersMap[followerId].discard(followeeId)\n\n\n# Your Twitter object will be instantiated and called as such:\n# obj = Twitter()\n# obj.postTweet(userId,tweetId)\n# param_2 = obj.getNewsFeed(userId)\n# obj.follow(followerId,followeeId)\n# obj.unfollow(followerId,followeeId)","hash":"19f81688405298828bd8db9fc670ed535a613a023b4617ea9761b20922b2a1f2","origins":[{"source":"solutions","path":"Design Twitter.py"}]}],"sources":["solutions"]},"topic-destinationcity":{"key":"topic-destinationcity","number":null,"title":"Destination City","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Destination City.py","code":"class Solution:\n    def destCity(self, paths: List[List[str]]) -> str:\n        originCities, destCities = set(), set()\n        for origin, dest in paths:\n            originCities.add(origin)\n            destCities.add(dest)\n        return list(destCities - originCities)[0]","hash":"51bceaed452852cee14fbff4998a3b3928d6eb2aeada40d1bedd050979d00858","origins":[{"source":"solutions","path":"Destination City.py"}]}],"sources":["solutions"]},"topic-detectcapital":{"key":"topic-detectcapital","number":null,"title":"Detect Capital","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Detect Capital.py","code":"class Solution:\n    def detectCapitalUse(self, word: str) -> bool:\n        if word.title() == word or word.upper() == word or word.lower() == word:\n            return True\n        return False","hash":"cf7bf645270371b20bc1a870dd371400bacd986dfdb0251a3c0ae00df83a13ea","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-08 Leetcoding Challenge/Detect Capital.py"}]},{"language":"python","name":"Detect Capital.py","code":"class Solution:\n    def detectCapitalUse(self, word: str) -> bool:\n        return word.isupper() or word.islower() or ((word[0].upper() + word[1:].lower()) == word)","hash":"c28baf80d1a44cdd6100befae19efc815f9e97c978e6a05f5835a781150a513d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-01 LeetCoding Challenge/Detect Capital.py"},{"source":"solutions","path":"LeetCoding Challenges/2023/2023-01 Leetcoding Challenge/Detect Capital.py"}]}],"sources":["solutions"]},"topic-detectcapitalbruteforce":{"key":"topic-detectcapitalbruteforce","number":null,"title":"Detect Capital Brute Force","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Detect Capital - Brute Force.py","code":"class Solution:\n    def detectCapitalUse(self, word: str) -> bool:\n        if len(word) > 2:\n            firstCharacterCapital = word[0].isupper()\n            secondCharacterCapital = word[1].isupper()\n            for i in range(2, len(word)):\n                if word[i].isupper() and firstCharacterCapital and secondCharacterCapital:\n                    continue\n                elif not secondCharacterCapital and word[i].islower():\n                    continue\n                else:\n                    return False\n            return True\n        elif len(word) == 2:\n            if word[0].islower() and word[1].isupper():\n                return False\n            else:\n                return True\n        else:\n            return True","hash":"e540c408a019f629f298ad842090b32c1faf5649c66bcba4514c0fb7c411487d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-08 Leetcoding Challenge/Detect Capital - Brute Force.py"}]}],"sources":["solutions"]},"topic-detectcyclesin2dgrid":{"key":"topic-detectcyclesin2dgrid","number":null,"title":"Detect Cycles in 2D Grid","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Detect Cycles in 2D Grid.py","code":"class Solution:\n    def containsCycle(self, grid: List[List[str]]) -> bool:\n        rows, cols, visited, directions = len(grid), len(grid[0]), set(), [(0, 1), (1, 0), (0, -1), (-1, 0)]\n        \n        def dfs(row, col, parentX, parentY, length):\n            visited.add((row, col))\n            for dirX, dirY in directions:\n                newRow, newCol = row + dirX, col + dirY\n                if newRow < 0 or newCol < 0 or newRow >= rows or newCol >= cols or (parentX == newRow and parentY == newCol):\n                    continue\n                if (newRow, newCol) in visited and length >= 4 and grid[row][col] == grid[newRow][newCol]:\n                    return True\n                elif grid[row][col] == grid[newRow][newCol]:\n                    if dfs(newRow, newCol, row, col, length + 1):\n                        return True\n            return False\n        \n        for row in range(rows):\n            for col in range(cols):\n                if (row, col) in visited:\n                    continue\n                if dfs(row, col, None, None, 1):\n                    return True\n        return False","hash":"41cc9e7ec8055c343d9a7ff6d97fe8c7cc4237af82dbaf8d8ce533ca7d6ddeb4","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 33/Detect Cycles in 2D Grid.py"}]}],"sources":["solutions"]},"topic-detectpatternoflengthmrepeatedkormoretimes":{"key":"topic-detectpatternoflengthmrepeatedkormoretimes","number":null,"title":"Detect Pattern of Length M Repeated K or More Times","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Detect Pattern of Length M Repeated K or More Times.py","code":"class Solution:\n    def containsPattern(self, arr: List[int], m: int, k: int) -> bool:\n        n, count = len(arr), 0\n        for i in range(n - m):\n            if arr[i] == arr[i + m]:\n                count += 1\n            else:\n                count = 0\n            if count == (m * (k - 1)):\n                return True\n        return False","hash":"cb13fab38b1f2764f7115304f605815d3e09f9a10d5fd9b1edbd95aa34b5661f","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 204/Detect Pattern of Length M Repeated K or More Times.py"}]}],"sources":["solutions"]},"topic-detectsquares":{"key":"topic-detectsquares","number":null,"title":"Detect Squares","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Detect Squares.py","code":"class DetectSquares:\n\n    def __init__(self):\n        self.freqMap = defaultdict(int)\n\n    def add(self, point: List[int]) -> None:\n        self.freqMap[(point[0], point[1])] += 1\n\n    def count(self, point: List[int]) -> int:\n        candidateX, candidateY = set(), set()\n        for p in self.freqMap:\n            if p[0] == point[0] and (p[0], p[1]) not in candidateY:\n                candidateY.add(p)\n            if p[1] == point[1] and (p[0], p[1]) not in candidateX:\n                candidateX.add(p)\n        result = 0\n        for x in candidateX:\n            for y in candidateY:\n                if abs(point[0] - x[0]) > 0 and abs(point[0] - x[0]) == abs(point[1] - y[1]) and (x[0], y[1]) in self.freqMap:\n                    result += (self.freqMap[x] * self.freqMap[y] * self.freqMap[(x[0], y[1])])\n        return result\n\n\n# Your DetectSquares object will be instantiated and called as such:\n# obj = DetectSquares()\n# obj.add(point)\n# param_2 = obj.count(point)","hash":"f1db94a5bcfd76812f2dd6d42aa52308576b7f351c433a6a651e41619197161e","origins":[{"source":"solutions","path":"Detect Squares.py"}]}],"sources":["solutions"]},"topic-determinecolorofachessboardsquare":{"key":"topic-determinecolorofachessboardsquare","number":null,"title":"Determine Color of a Chessboard Square","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Determine Color of a Chessboard Square.py","code":"class Solution:\n    def squareIsWhite(self, coordinates: str) -> bool:\n        hashMap = {'a': 1, 'b': 2, 'c': 3, 'd': 4, 'e': 5, 'f': 6, 'g': 7, 'h': 8}\n        return ((hashMap[coordinates[0]] + int(coordinates[1])) % 2) == 1","hash":"17e61c131ad64e9e27a74e2a91a39e77ca8a5f6ca382f4ba46526d78f1f757c5","origins":[{"source":"solutions","path":"Determine Color of a Chessboard Square.py"}]}],"sources":["solutions"]},"topic-distringmatch":{"key":"topic-distringmatch","number":null,"title":"DI String Match","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"DI String Match.py","code":"class Solution:\n    def diStringMatch(self, S: str) -> List[int]:\n        low, high, result = 0, len(S), []\n        for char in S:\n            if char == 'I':\n                result.append(low)\n                low += 1\n            else:\n                result.append(high)\n                high -= 1\n        return result + [low]","hash":"0b9a7b510e8a00371ce636b4ee97efd5c6c310ec2fff0a81f9b2a971ac9477bd","origins":[{"source":"solutions","path":"DI String Match.py"}]}],"sources":["solutions"]},"topic-diagonaltraverse":{"key":"topic-diagonaltraverse","number":null,"title":"Diagonal Traverse","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Diagonal Traverse.py","code":"class Solution:\n    def findDiagonalOrder(self, matrix: List[List[int]]) -> List[int]:\n        if not matrix or not matrix[0]:\n            return []\n        rows, cols, result, directionUp = len(matrix), len(matrix[0]), [], True\n        for currentSum in range(rows + cols - 1):\n            if directionUp:\n                if currentSum < rows:\n                    row, col = currentSum, 0\n                else:\n                    row, col = rows - 1, currentSum - rows + 1\n                while row > -1 and col < cols:\n                    result.append(matrix[row][col])\n                    row -= 1\n                    col += 1\n            else:\n                if currentSum < cols:\n                    row, col = 0, currentSum\n                else:\n                    row, col = currentSum - cols + 1, cols - 1\n                while col > -1 and row < rows:\n                    result.append(matrix[row][col])\n                    row += 1\n                    col -= 1\n            directionUp = not directionUp\n        return result","hash":"4fd8d0434450f4cda094841c8498f4f46828f8c2e523fa5e8453aeb76cf15f80","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-12 Leetcoding Challenge/Diagonal Traverse.py"}]}],"sources":["solutions"]},"topic-diagonaltraverseii":{"key":"topic-diagonaltraverseii","number":null,"title":"Diagonal Traverse II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Diagonal Traverse II.py","code":"class Solution:\n    def findDiagonalOrder(self, nums: List[List[int]]) -> List[int]:\n        elements = []\n        for row in range(len(nums)):\n            for col in range(len(nums[row])):\n                elements.append((row + col, row * -1, nums[row][col]))\n        elements.sort()\n        return [x[2] for x in elements]","hash":"0ce18011016759ff933b259a8093d2cca424dff2ee9a59dac05b89a10f46cf5b","origins":[{"source":"solutions","path":"Diagonal Traverse II.py"}]}],"sources":["solutions"]},"topic-diameterofbinarytree":{"key":"topic-diameterofbinarytree","number":null,"title":"Diameter of Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Diameter of Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def diameterOfBinaryTree(self, root: TreeNode) -> int:\n        diameter = 1\n        \n        def depthOfTree(node):\n            nonlocal diameter\n            if node is None:\n                return 0\n            else:\n                leftTreeDepth = depthOfTree(node.left)\n                rightTreeDepth = depthOfTree(node.right)\n                diameter = max(diameter, 1 + leftTreeDepth + rightTreeDepth)\n                return 1 + max(leftTreeDepth, rightTreeDepth)\n        \n        depthOfTree(root)\n        return diameter - 1","hash":"bf616f7089cd8c5dd1e138926b2fb1edea12ff559acf812fcabf83449d72118f","origins":[{"source":"solutions","path":"Diameter of Binary Tree.py"},{"source":"solutions","path":"Google Interview Questions/Diameter of Binary Tree.py"}]}],"sources":["solutions"]},"topic-dietplanperformance":{"key":"topic-dietplanperformance","number":null,"title":"Diet Plan Performance","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Diet Plan Performance.py","code":"class Solution:\n    def dietPlanPerformance(self, calories: List[int], k: int, lower: int, upper: int) -> int:\n        T = sum(calories[:k])\n        def evaluate(T):\n            if T < lower:\n                return -1\n            elif T > upper:\n                return 1\n            else:\n                return 0\n        points = evaluate(T)\n        for i in range(k, len(calories)):\n            T += (calories[i] - calories[i - k])\n            points += evaluate(T)\n        return points","hash":"a2be8afad866d3cbd521cb3c9966ebc353eaddd4c409949519a0e141a107281f","origins":[{"source":"solutions","path":"Diet Plan Performance.py"}]}],"sources":["solutions"]},"algorithm-dijkstra":{"key":"algorithm-dijkstra","number":null,"title":"dijkstra","difficulty":"Unknown","tags":["Algorithm Reference"],"documents":[],"sources":["algorithms"],"solutions":[{"language":"python","name":"dijkstra.py","code":"\"\"\"\npseudo-code\n\nDIJKSTRA(graph G, start vertex s, destination vertex d):\n\n// all nodes initially unexplored\n\n1 -  let H = min heap data structure, initialized with (0, s)\n     // 0 is the distance from start vertex s\n2 -  let costs = dictionary to store minimum costs to reach each node,\n     initialized with {s: 0}\n3 -  while H is non-empty:\n4 -    remove the first node and cost from H, call them U and cost\n5 -    if U has been previously explored:\n6 -      continue // skip further processing and go back to while loop, line 3\n7 -    mark U as explored\n8 -    if U is d:\n9 -      return cost // total cost from start to destination vertex\n10 -   for each neighbor V and edge cost c of U in G:\n11 -     if V has been previously explored:\n12 -       continue to next neighbor V in line 10\n13 -     total_cost = cost + c\n14 -     if total_cost is less than costs.get(V, ∞):\n15 -       update costs[V] to total_cost\n16 -       add (total_cost, V) to H\n\n// At the end, if destination d is not reachable, return -1\n\nYou can think at cost as a distance where Dijkstra finds the shortest distance\nbetween vertices s and v in a graph G. The use of a min heap as H guarantees\nthat if a vertex has already been explored there will be no other path with\nshortest distance, that happens because heapq.heappop will always return the\nnext vertex with the shortest distance, considering that the heap stores not\nonly the distance between previous vertex and current vertex but the entire\ndistance between each vertex that makes up the path from start vertex to target\nvertex.\n\"\"\"\n\nimport heapq\n\n\ndef dijkstra(graph: dict[str, list[tuple[str, int]]], start: str, end: str) -> int:\n    \"\"\"Return the cost of the shortest path between vertices start and end.\n\n    >>> dijkstra(G, \"E\", \"C\")\n    6\n    >>> dijkstra(G2, \"E\", \"F\")\n    3\n    >>> dijkstra(G3, \"E\", \"F\")\n    3\n    \"\"\"\n    heap: list[tuple[int, str]] = [(0, start)]  # (cost, node)\n    visited: set[str] = set()\n    costs: dict[str, int] = {start: 0}  # Store minimum costs to reach each node\n\n    while heap:\n        cost, u = heapq.heappop(heap)\n        if u in visited:\n            continue\n        visited.add(u)\n        if u == end:\n            return cost\n\n        for v, c in graph[u]:\n            if v in visited:\n                continue\n            next_cost = cost + c\n            # Only push to heap if a cheaper path is found\n            if next_cost < costs.get(v, float(\"inf\")):\n                costs[v] = next_cost\n                heapq.heappush(heap, (next_cost, v))\n\n    return -1\n\n\nG = {\n    \"A\": [(\"B\", 2), (\"C\", 5)],\n    \"B\": [(\"A\", 2), (\"D\", 3), (\"E\", 1), (\"F\", 1)],\n    \"C\": [(\"A\", 5), (\"F\", 3)],\n    \"D\": [(\"B\", 3)],\n    \"E\": [(\"B\", 4), (\"F\", 3)],\n    \"F\": [(\"C\", 3), (\"E\", 3)],\n}\n\nr\"\"\"\nLayout of G2:\n\nE -- 1 --> B -- 1 --> C -- 1 --> D -- 1 --> F\n \\                                         /\\\n  \\                                        ||\n    ----------------- 3 --------------------\n\"\"\"\nG2 = {\n    \"B\": [(\"C\", 1)],\n    \"C\": [(\"D\", 1)],\n    \"D\": [(\"F\", 1)],\n    \"E\": [(\"B\", 1), (\"F\", 3)],\n    \"F\": [],\n}\n\nr\"\"\"\nLayout of G3:\n\nE -- 1 --> B -- 1 --> C -- 1 --> D -- 1 --> F\n \\                                         /\\\n  \\                                        ||\n    -------- 2 ---------> G ------- 1 ------\n\"\"\"\nG3 = {\n    \"B\": [(\"C\", 1)],\n    \"C\": [(\"D\", 1)],\n    \"D\": [(\"F\", 1)],\n    \"E\": [(\"B\", 1), (\"G\", 2)],\n    \"F\": [],\n    \"G\": [(\"F\", 1)],\n}\n\nshort_distance = dijkstra(G, \"E\", \"C\")\nprint(short_distance)  # E -- 3 --> F -- 3 --> C == 6\n\nshort_distance = dijkstra(G2, \"E\", \"F\")\nprint(short_distance)  # E -- 3 --> F == 3\n\nshort_distance = dijkstra(G3, \"E\", \"F\")\nprint(short_distance)  # E -- 2 --> G -- 1 --> F == 3\n\nif __name__ == \"__main__\":\n    import doctest\n\n    doctest.testmod()\n","hash":"81a0c6f766b6dbc55ce2239ca4038de2a686bf609ba84ecad033c65ec83ad707","origins":[{"source":"algorithms","path":"graphs/dijkstra.py","url":"https://github.com/TheAlgorithms/Python/blob/25c712f2692449e91a57748d328ef34fccf25654/graphs/dijkstra.py","commit":"25c712f2692449e91a57748d328ef34fccf25654"}]}]},"topic-distancebetweenbusstops":{"key":"topic-distancebetweenbusstops","number":null,"title":"Distance Between Bus Stops","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Distance Between Bus Stops.py","code":"class Solution:\n    def distanceBetweenBusStops(self, distance: List[int], start: int, destination: int) -> int:\n        totalDistance, currentDist, i = sum(distance), 0, start\n        while i != destination:\n            currentDist += distance[i]\n            i = (i + 1) % len(distance)\n        return min(currentDist, totalDistance - currentDist)","hash":"41d3dc5b414577b27f8536ee8cb1164908b2840fbed87b9d107a7b68e7f56818","origins":[{"source":"solutions","path":"Distance Between Bus Stops.py"}]}],"sources":["solutions"]},"topic-distantbarcodes":{"key":"topic-distantbarcodes","number":null,"title":"Distant Barcodes","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Distant Barcodes.py","code":"class Solution:\n    def rearrangeBarcodes(self, barcodes: List[int]) -> List[int]:\n        freqMap = Counter(barcodes)\n        heap = [(-freq, val) for val, freq in freqMap.items()]\n        heapify(heap)\n        index, result = 0, [0] * len(barcodes)\n        while heap:\n            freq, val = heappop(heap)\n            for _ in range(-freq):\n                result[index] = val\n                index += 2\n                if index >= len(barcodes):\n                    index = 1\n        return result","hash":"f7332538df3fb63b67419e5bf4600459e8714cc40032f783db9901cae8384e92","origins":[{"source":"solutions","path":"Distant Barcodes.py"}]}],"sources":["solutions"]},"topic-distributecandies":{"key":"topic-distributecandies","number":null,"title":"Distribute Candies","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Distribute Candies.py","code":"class Solution:\n    def distributeCandies(self, candyType: List[int]) -> int:\n        return min(len(candyType) // 2, len(set(candyType)))","hash":"a0e73a5dde801e0cdaff69590f231fc5a7fb0686e6f6571f91d448a7cd4551b8","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-03 Leetcoding Challenge/Distribute Candies.py"}]}],"sources":["solutions"]},"topic-distributecandiestopeople":{"key":"topic-distributecandiestopeople","number":null,"title":"Distribute Candies to People","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Distribute Candies to People.py","code":"class Solution:\n    def distributeCandies(self, candies: int, num_people: int) -> List[int]:\n        n = num_people\n        p = int((2 * candies + 0.25)**0.5 - 0.5) \n        remaining = int(candies - (p + 1) * p * 0.5)\n        rows, cols = p // n, p % n\n        d = [0] * n\n        for i in range(n):\n            d[i] = (i + 1) * rows + int(rows * (rows - 1) * 0.5) * n\n            if i < cols:\n                d[i] += i + 1 + rows * n\n        d[cols] += remaining\n        return d","hash":"62acec8164365d1fd7d2390b08511557a8a7339b5b5a33f15d147a6eb26928dd","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-08 Leetcoding Challenge/Distribute Candies to People.py"}]}],"sources":["solutions"]},"topic-distributecoinsinbinarytree":{"key":"topic-distributecoinsinbinarytree","number":null,"title":"Distribute Coins in Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Distribute Coins in Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def distributeCoins(self, root: TreeNode) -> int:\n        self.result = 0\n        def dfs(node):\n            if not node:\n                return 0\n            L, R = dfs(node.left), dfs(node.right)\n            self.result += abs(L) + abs(R)\n            return node.val + L + R - 1\n        dfs(root)\n        return self.result","hash":"9934ffe9340a98cdd75917cc74b3882c07cec5c072b6c47b12fd8760cd81fed3","origins":[{"source":"solutions","path":"Distribute Coins in Binary Tree.py"}]}],"sources":["solutions"]},"topic-dividearrayintoequalpairs":{"key":"topic-dividearrayintoequalpairs","number":null,"title":"Divide Array Into Equal Pairs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Divide Array Into Equal Pairs.py","code":"class Solution:\n    def divideArray(self, nums: List[int]) -> bool:\n        freqMap = Counter(nums)\n        for val in freqMap.values():\n            if val % 2 == 1:\n                return False\n        return True","hash":"e63f3ea9eec25141da638cff7b8dd6b94a76f40eab4d6911ab79cff7bf94f759","origins":[{"source":"solutions","path":"Divide Array Into Equal Pairs.py"}]}],"sources":["solutions"]},"topic-divisorgame":{"key":"topic-divisorgame","number":null,"title":"Divisor Game","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Divisor Game.py","code":"class Solution:\n    def divisorGame(self, N: int) -> bool:\n        return N % 2 == 0","hash":"f1928962b341c1b4fb224f76734669d416dfa79e125f30bc73d73ad5d1e1c93f","origins":[{"source":"solutions","path":"Divisor Game.py"},{"source":"solutions","path":"Mock Interviews/Google/Online Assessment 04/Divisor Game.py"}]}],"sources":["solutions"]},"topic-dominoandtrominotiling":{"key":"topic-dominoandtrominotiling","number":null,"title":"Domino and Tromino Tiling","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Domino and Tromino Tiling.py","code":"class Solution:\n    def numTilings(self, n: int) -> int:\n        MOD = (10**9) + 7\n\n        @cache\n        def numTilingsD(N):\n            if N <= 2:\n                return 2 if N == 2 else 1\n            return (numTilingsD(N - 2) + numTilingsD(N - 1) + (2 * numTilingsT(N - 1))) % MOD\n        \n        @cache\n        def numTilingsT(N):\n            if N <= 2:\n                return 1 if N == 2 else 0\n            return (numTilingsD(N - 2) + numTilingsT(N - 1)) % MOD\n        \n        return numTilingsD(n)","hash":"51ff7e8a6437f1435cd7fcd54a7a8e45570095bd6d245f50472e63bf391d68e5","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-12 Leetcoding Challenge/Domino and Tromino Tiling.py"}]}],"sources":["solutions"]},"topic-duplicateemails":{"key":"topic-duplicateemails","number":null,"title":"Duplicate Emails","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"sql","name":"Duplicate Emails.sql","code":"# Write your MySQL query statement below\nSELECT Email FROM Person GROUP BY Email HAVING count(Email) > 1;","hash":"869af8402fe8577ff24828c71b2ae67231b053ba1292c01b7f93140ecd141b7a","origins":[{"source":"solutions","path":"Duplicate Emails.sql"}]}],"sources":["solutions"]},"topic-duplicatezeros":{"key":"topic-duplicatezeros","number":null,"title":"Duplicate Zeros","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Duplicate Zeros.py","code":"class Solution:\n    def duplicateZeros(self, arr: List[int]) -> None:\n        \"\"\"\n        Do not return anything, modify arr in-place instead.\n        \"\"\"\n        possibleDups, arrLength = 0, len(arr) - 1\n        for i in range(arrLength + 1):\n            if i > arrLength - possibleDups:\n                break\n            if arr[i] == 0:\n                if i == arrLength - possibleDups:\n                    arr[arrLength] = 0\n                    arrLength -= 1\n                    break\n                possibleDups += 1\n        last = arrLength - possibleDups\n        for i in range(last, -1, -1):\n            if arr[i] == 0:\n                arr[i + possibleDups] = 0\n                possibleDups -= 1\n                arr[i + possibleDups] = 0\n            else:\n                arr[i + possibleDups] = arr[i]","hash":"77dc0dc1995f2dd3cf26f929e2af5abea8a686a7c22288c7bce41e306ed89021","origins":[{"source":"solutions","path":"Arrays/Duplicate Zeros.py"},{"source":"solutions","path":"Duplicate Zeros.py"},{"source":"solutions","path":"Mock Interviews/Google/Phone Interview 02/Duplicate Zeros.py"}]}],"sources":["solutions"]},"topic-employeebonus":{"key":"topic-employeebonus","number":null,"title":"Employee Bonus","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"sql","name":"Employee Bonus.sql","code":"SELECT name, bonus FROM Employee LEFT JOIN Bonus ON Employee.empId = Bonus.empId WHERE bonus < 1000 OR bonus is NULL;","hash":"0b8e83a2b617dd7527d035ff6df7e8a83c5bd794e9d4fe4861afcaf790bcee53","origins":[{"source":"solutions","path":"Employee Bonus.sql"}]}],"sources":["solutions"]},"topic-employeefreetime":{"key":"topic-employeefreetime","number":null,"title":"Employee Free Time","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Employee Free Time.py","code":"\"\"\"\n# Definition for an Interval.\nclass Interval:\n    def __init__(self, start: int = None, end: int = None):\n        self.start = start\n        self.end = end\n\"\"\"\n\nclass Solution:\n    def employeeFreeTime(self, schedule: '[[Interval]]') -> '[Interval]':\n        events, OPEN, CLOSE = [], 0, 1\n        for employee in schedule:\n            for interval in employee:\n                events.append((interval.start, OPEN))\n                events.append((interval.end, CLOSE))\n        events.sort()\n        result, prev, balance = [], None, 0\n        for time, state in events:\n            if balance == 0 and prev is not None:\n                result.append(Interval(prev, time))\n            prev = time\n            balance += 1 if state is OPEN else -1\n        return result","hash":"e03ed1100611a9b900488d38fedf52f09fc458c014f77d553dd426fe1c59bd2b","origins":[{"source":"solutions","path":"Employee Free Time.py"}]}],"sources":["solutions"]},"topic-employeeimportance":{"key":"topic-employeeimportance","number":null,"title":"Employee Importance","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Employee Importance.py","code":"\"\"\"\n# Definition for Employee.\nclass Employee:\n    def __init__(self, id: int, importance: int, subordinates: List[int]):\n        self.id = id\n        self.importance = importance\n        self.subordinates = subordinates\n\"\"\"\n\nclass Solution:\n    def getImportance(self, employees: List['Employee'], employeeId: int) -> int:\n        subordinationGraph = defaultdict(list)\n        importanceGraph = defaultdict(int)\n        for employee in employees:\n            subordinationGraph[employee.id].extend(employee.subordinates)\n            importanceGraph[employee.id] = employee.importance\n        if employeeId not in importanceGraph:\n            return 0\n        importance = importanceGraph[employeeId]\n        \n        def dfs(node):\n            nonlocal importance\n            for subordinate in subordinationGraph[node]:\n                importance += importanceGraph[subordinate]\n                dfs(subordinate)\n        \n        dfs(employeeId)\n        return importance","hash":"26e1e098b1c62c9dac2dee019c10ef3e2abef0fa19e67627e4fe1d6f8ad43fd3","origins":[{"source":"solutions","path":"Employee Importance.py"}]}],"sources":["solutions"]}});
